 const tr=(value:string)=>en?(labelEn[value]??value):value
 const sheets=useMemo(()=>definitions(plantType),[plantType]),key='process-plant:'+plantType+':'+project.id+':excel-sequence-v2'
 const [data,setData]=useState<Record<string,Row[]>>({}),[selected,setSelected]=useState(sheets[0].id),[ready,setReady]=useState(false),[saved,setSaved]=useState(''),[loadedKey,setLoadedKey]=useState(''),[comfarPaste,setComfarPaste]=useState('')
 useEffect(()=>{let alive=true;setReady(false);setSaved('');setLoadedKey('');setData({});localStore.get<Record<string,Row[]>>(key).then(v=>{if(alive){setData(migrateStoredData(v??{},sheets,plantType));setLoadedKey(key);setReady(true)}}).catch(()=>{if(alive){setData({});setReady(true)}});return()=>{alive=false}},[key])
 useEffect(()=>{if(ready&&loadedKey===key)void localStore.set(key,data).then(()=>setSaved(new Date().toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'})))},[ready,loadedKey,key,data])
 const current=sheets.find(x=>x.id===selected)??sheets[0],rows=data[current.id]??makeRows(current,plantType)
 const updateRows=(next:Row[])=>setData(old=>({...old,[current.id]:next}))
 const payrollData=data.payroll??makeRows(payrollSheet,plantType)
 const machineStructureData=data.machineStructures??makeStructureRows()
 const updateMachineStructureCell=(id:string,key:string,value:Cell)=>setData(old=>({...old,machineStructures:machineStructureData.map(row=>row.id===id?{...row,values:{...row.values,[key]:value}}:row)}))
 const staffSheet=sheets.find(x=>x.id==='staff')!
 const staffData=data.staff??makeRows(staffSheet,plantType)
 const staffTotals=staffData.reduce((totals,row)=>{if(row.section||row.label==='جمع')return totals;const allocation=row.values.allocation===undefined?100:Number(row.values.allocation);const factor=Math.max(0,Math.min(100,allocation))/100;for(const key of ['expert','technician','secretary','operator','driver','laborer'] as const)totals[key]+=Number(row.values[key]??0)*factor;return totals},{expert:0,technician:0,secretary:0,operator:0,driver:0,laborer:0})
 const managerCount=Math.round(staffTotals.expert/25)
 const payrollCounts=[managerCount,managerCount*4,Math.max(0,staffTotals.expert-managerCount-managerCount*4),staffTotals.technician,staffTotals.secretary,staffTotals.operator+staffTotals.driver,staffTotals.laborer]
 const payrollDisplayData:Row[]=payrollData.map((row,i)=>{const v=row.values,count=payrollCounts[i]??Number(v.count??0),salary=Number(v.salary??0),insurance=Math.round(salary*.23),overtime=salary*.4,monthlyTotal=salary+insurance+overtime,annualWage=monthlyTotal*12,bonus=salary*2,seniority=salary,annualPerPerson=annualWage+bonus+seniority;return{...row,values:{...v,count,monthlyTotal,annualWage,annualPerPerson,annualGroup:annualPerPerson*count} as Record<string,Cell>}})
 const payrollBaseTotal=payrollDisplayData.reduce((sum,row)=>sum+Number(row.values.annualGroup??0),0)
 const payrollOverhead=payrollBaseTotal*.2
 const payrollGrandTotal=payrollBaseTotal+payrollOverhead
 const updatePayrollRows=(next:Row[])=>setData(old=>({...old,payroll:next}))
 const updatePayrollCell=(id:string,key:string,value:Cell)=>updatePayrollRows(payrollData.map(row=>row.id===id?{...row,values:{...row.values,[key]:value}}:row))
 const addPayrollRow=()=>updatePayrollRows([...payrollData,{id:'payroll-custom-'+Date.now(),label:'ردیف جدید',values:Object.fromEntries(payrollSheet.columns.map(col=>[col.key,col.numeric?0:'']))}])
 const updateCell=(id:string,key:string,value:Cell)=>updateRows(rows.map(row=>row.id===id?{...row,values:{...row.values,[key]:value}}:row))
 const addRow=()=>{const values:Record<string,Cell>=Object.fromEntries(current.columns.map(col=>[col.key,col.numeric?0:'']));if(['land','site','vehicles','infrastructure','office','preop','staff'].includes(current.id))values.allocation=100;if(current.id==='site')values.year=1;if(current.id==='buildings')values.sharedFactor=0;updateRows([...rows,{id:current.id+'-custom-'+Date.now(),label:'ردیف جدید',values}])}
 const machineDetailLabels=['تجهیزات فرایندی','تجهیزات برقی','تجهیزات ابزاردقیق، کنترل و اتوماسیون','سیستم‌های جانبی','حمل و نقل','تأمین مواد مصرفی ۶ ماهه جهت راه‌اندازی','قطعات یدکی دو سالانه']
const machineDataRows=data.machines??makeRows(sheets.find(x=>x.id==='machines')!,plantType)
const machineLineAmount=(row:Row):number=>{const processFields=plantType==='dri'?['foreignDri','localDri']:['foreignEaf','localEaf','foreignCcm','localCcm'],calc=(x:Row)=>processFields.reduce((sum,key)=>sum+Number(x.values[key]??0),0)+(Number(x.values.foreignStock??0)+Number(x.values.localStock??0))*Math.max(0,Math.min(100,Number(x.values.sharedAllocation??0)))/100,source=row.label==='ساخت و تأمین تجهیزات'?machineDataRows.filter(x=>machineDetailLabels.includes(x.label)):[row];return source.reduce((sum,x)=>sum+calc(x),0)}
const capexAmount=(sheetId:string,row:Row):number=>{const v=row.values,n=(key:string)=>Number(v[key]??0)||0,allocation=v.allocation===undefined?1:Math.max(0,Math.min(100,n('allocation')))/100
 if(sheetId==='land')return n('total')||n('qty')*n('unitPrice')*allocation
 if(sheetId==='site')return n('total')||n('qty')*n('unitPrice')*allocation
 if(sheetId==='buildings')return n('total')||(n('qty')*n('unitPrice')+n('equipment'))*(1-Math.max(0,Math.min(1,n('sharedFactor'))))*allocation
 if(sheetId==='machines')return machineDetailLabels.includes(row.label)?0:machineLineAmount(row)
 if(sheetId==='vehicles')return n('total')||n('qty')*n('unitPrice')*allocation
 if(sheetId==='preop'){
  const source=data.preop??makeRows(sheets.find(x=>x.id==='preop')!,plantType)
  if(row.section||row.label==='جمع کل هزینه‌های قبل از بهره‌برداری')return 0
  if(preopGroups[row.label])return source.filter(x=>preopGroups[row.label].includes(x.label)).reduce((sum,x)=>sum+Number(x.values.amount??0)*Math.max(0,Math.min(100,Number(x.values.allocation??100)))/100,0)
  if(row.label.includes('بیمه ریسک'))return n('amount')?n('amount')*allocation:Math.round(fixedInvestment/1000000)*1000000*2.5/1000
  if(row.label.includes('اخذ وام'))return n('amount')?n('amount')*allocation:Math.round(fixedInvestment/1000000)*1000000*1.25/1000
  if(row.label.includes('۵٪')){const baseLabels=[...Object.keys(preopGroups),'مشاور مادر و همراهی مدیریت پروژه','بیمه ریسک پروژه — ۲٫۵ در هزار سرمایه‌گذاری ثابت','هزینه اخذ وام — ۱٫۲۵ در هزار سرمایه‌گذاری ثابت'];const base=source.filter(x=>baseLabels.includes(x.label)).reduce((sum,x)=>sum+capexAmount('preop',x),0);return n('amount')?n('amount')*allocation:base*.05}
  if(row.label==='مشاور مادر و همراهی مدیریت پروژه')return n('amount')*allocation
  if(Object.values(preopGroups).some(labels=>labels.includes(row.label)))return 0
  return n('amount')*allocation
 }
 if(sheetId==='infrastructure'||sheetId==='office')return n('amount')*allocation
 return n('amount')||n('total')||n('annualCost')
}
const financeProjectSheet=sheets.find(x=>x.id==='project')!
const financeProjectRows=data.project??makeRows(financeProjectSheet,plantType)
const financeRow=(label:string)=>financeProjectRows.find(row=>row.label===label)
const financeValue=(label:string,fallback=0)=>Number(financeRow(label)?.values.value??fallback)||0
const financeText=(label:string,fallback='')=>String(financeRow(label)?.values.value??fallback)
const constructionYears=Math.max(1,Math.min(18,Math.floor(financeValue('تعداد سال دوره ساخت',4))))
const operatingYears=Math.max(1,Math.min(18,Math.floor(financeValue('تعداد سال دوره بهره‌برداری',15))))
const constructionStartDate=financeText('تاریخ شروع دوره ساخت (شمسی)','1405/08/23')
const constructionEndDate=financeText('تاریخ پایان دوره ساخت (شمسی)','1409/08/22')
const operationStartDate=financeText('تاریخ شروع دوره بهره‌برداری (شمسی)','1409/08/23')
const operationEndDate=financeText('تاریخ پایان دوره بهره‌برداری (شمسی)','1424/08/22')
const materialCapacity=Math.max(0,financeValue('ظرفیت اسمی سالانه تولید (تن)',plantType==='dri'?1760000:1200000))
const capexBySheet=(id:string):number=> (data[id]??makeRows(sheets.find(x=>x.id===id)!,plantType)).reduce((sum,row)=>sum+capexAmount(id,row),0)
const capexReferenceCapacityInput=financeValue('ظرفیت مرجع برآورد CAPEX (تن)',plantType==='dri'?1760000:1200000)
const capexReferenceCapacity=Math.max(1,capexReferenceCapacityInput)
const capexRatio=materialCapacity/capexReferenceCapacity
const capexElasticity:Record<string,string>={land:'توان مقیاس زمین',site:'توان مقیاس محوطه‌سازی',buildings:'توان مقیاس ساختمان‌ها',machines:'توان مقیاس ماشین‌آلات',infrastructure:'توان مقیاس تأسیسات',vehicles:'توان مقیاس وسائط نقلیه',office:'توان مقیاس تجهیزات اداری'}
const capexScaleFactor=(id:string)=>calculateCapacityScaledCapex(1,capexReferenceCapacity,materialCapacity,Math.max(0,Math.min(1,financeValue(capexElasticity[id]??'',.65)))).factor
const capexBaseBySheet=(id:string)=>capexBySheet(id)*capexScaleFactor(id)
const fixedBase:number=capexBaseBySheet('land')+capexBaseBySheet('site')+capexBaseBySheet('buildings')+capexBaseBySheet('infrastructure')+capexBaseBySheet('vehicles')+capexBaseBySheet('office')
const contingency:number=Math.round(fixedBase*.05)
const fixedInvestment:number=fixedBase+capexBaseBySheet('machines')+contingency
const preOperating:number=capexBySheet('preop')
const capexTotal:number=fixedInvestment+preOperating
